  ),

  usageModelAliases: Schema.Record(TrimmedNonEmptyString, TrimmedNonEmptyString).pipe(
    Schema.withDecodingDefault(Effect.succeed({})),
  ),
});

export const RuntimeMode = Schema.Literals([
  "approval-required",
  "auto-accept-edits",
